(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ia"] = {"ui":{"skip":"Saltar al contento","back":"← Retornar a AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Elige un lingua","lang.search":"Cercar linguas","lang.none":"Nulle lingua corresponde","lang.notYet":"{name} non es ancora traducite","theme.aria":"Cambiar inter thema clar e obscur","theme.toLight":"Cambiar al thema clar","theme.toDark":"Cambiar al thema obscur","words.underline":"Sublinear iste parolas sur le pagina","words.underlineHelp":"Passa le mus super un parola punctate, o tocca lo, pro vider lo que illo significa.","index.title":"AI-gile: tu equipa de disveloppatores IA, sur un sol tabula","index.description":"AI-gile es un tabula kanban pro equipas de programmation IA. Illes travalia durante que tu dormi; tu recipe un curte pila de cosas a decider, a testar e a acceptar.","hero.logoAlt":"Icone del tabula AI-gile","hero.h1.html":"Tu equipa de disveloppatores IA, sur un sol&nbsp;tabula.","hero.alpha":"🐣 Pre-alpha claudite","hero.alphaTitle":"Precoce e non finite: gratias pro probar lo!","hero.lede":"Illes construe durante que tu dormi. Tu te expergisce con un curte pila: alicun questiones, alicun cosas a testar, un o duo diamantes purpure. Clicca, accepta, retorna a tu caffe.","dl.windows":"Application Windows","dl.browser":"Executa lo in tu navigator","dl.soon":"Proximemente","dl.notify":"🔔 Dice me quando illo aperi","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, ma le equipa non ha besonio de caffe de stand-up. (Illes face stand-ups totevia.)","pitch.h2":"AI-gile in tanto parolas como tu vole","pitch.lede":"Elige un longor, ab un parola usque a 144. Cata longor ha su proprie description, scribite pro iste dimension. Tira le glissor o usa le sagittas.","pitch.rangeLabel":"Longor in parolas","pitch.dice":"🎲 un altere version","pitch.words.one":"{n} parola","pitch.words.other":"{n} parolas","pitch.letters.one":"{n} littera","pitch.letters.other":"{n} litteras","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characteres","count.line.html.one":"{n} carta sur le tabula in iste momento","count.line.html.other":"{n} cartas sur le tabula in iste momento","features.aria":"Lo que illo face","f.pile.h":"Un sol pila pro te","f.pile.html":"<b>Pro te</b> contine toto lo que expecta te, de tote le projectos: questiones, cosas a testar, tascas que solmente un human pote facer. Tu cauda dice lo que veni proxime e quante tempore illo prende.","f.sleep.h":"Equipas que travalia durante que tu dormi","f.sleep.p":"Cata projecto ha un chef e un equipa de agentes IA. Commenta un carta e le equipa se expergisce, face le travalio e lo retorna a te con passos que un human fatigate pote sequer.","f.tester.h":"Un testator IA verifica primo","f.tester.p":"Ante que alco te arriva, un testator seque le passos in un copia del application e monstra lo que illo ha vidite, con un captura de schermo. Folia le cartas passate e accepta con un clic.","f.proof.h":"Provas, non promissas","f.proof.p":"Cata consigna monstra lo que ha cambiate: le files, le diff, le capturas de schermo. Nulle besonio de aperir cata application pro saper si illo es finite.","f.chat.h":"Conversa con tu chefs","f.chat.p":"Un barra a stilo de Discord: un icone per projecto, diamantes purpure pro lo que ha besonio de te. Invia un idea a un chef; ille lo transforma in cartas e un plano, con un button ✅ Go.","f.tidy.h":"Se tene in ordine","f.tidy.p":"Cartas connexe se fusiona in un sol, titulos confuse se corrige, e un verification de jetones tene le codice legier. Minus cosas inter le quales cambiar, minus a pensar.","f.private.h":"Tue, sur tu computator","f.private.li1":"Le tabula functiona sur tu proprie machina e responde solmente a te.","f.private.li2":"Messages privatissime inter personas es cryptate de fin a fin.","f.private.li3":"Nulle contos, nulle traciatores, nulle cookies.","f.lang.h":"In tu lingua","f.lang.p":"Plus de 120 linguas, del nederlandese, gallese e japonese al pirata, Yoda e klingon, con un cambio rapide al anglese pro le parolas de disveloppator.","tl.aria":"Chronologia ab le prime conversation usque al plano","tl.h2":"Ab le prime conversation a lo que veni","tl.lede":"Datas e horas real, in tu proprie fuso horari. Post hodie il es le plano, sin datas promittite.","tl.today":"Hodie","tl.planned":"planificate","tl.cards.one":"{n} carta","tl.cards.other":"{n} cartas","join.h2":"Participa","join.lede":"AI-gile es construite per un micre human e un grande numero de agentes patiente. Pro ora illo es private, in un alpha claudite con amicos. Vole probar lo quando illo aperi?","join.btn":"Registrar interesse","join.small":"Nos te scribera per e-mail, nihil altere","footer.tag":"AI-gile. Nulle traciatores, nulle cookies, nulle caffe de stand-up.","footer.licence":"Licentia commercial","footer.status":"Stato","footer.privacy":"Lo que nos guarda","form.sending":"Invio…","form.failed":"Isto non functionava: retenta plus tarde.","form.offline":"Non poteva attinger AI-gile: retenta plus tarde.","form.keep":"Nos usa isto solmente pro responder te, postea nos lo dele. Nulle traciatores, nulle cookies.","form.keepLink":"Lo que nos guarda","interest.title":"AI-gile: dice me quando le alpha aperi","interest.description":"Lassa tu e-mail pro saper quando le alpha o beta claudite de AI-gile aperi.","interest.h1":"🔔 Dice me quando illo aperi","interest.lede":"AI-gile es in pre-alpha claudite. Lassa tu e-mail e nos te scribera un vice, quando il ha un placia pro te.","interest.email":"Tu e-mail","interest.which":"Qual test?","interest.alpha":"Alpha claudite: precoce, rude, multe cambiamentos","interest.beta":"Beta: plus stabile, plus tarde","interest.both":"Un o le altere, le qual veni primo","interest.submit":"Pone me in le lista","interest.thanks":"Gratias! Tu es in le lista.","licence.title":"AI-gile: licentia commercial","licence.description":"Usa AI-gile in tu empresa? Demanda un licentia commercial gratuite.","licence.h1":"📜 Licentia commercial","licence.lede":"Usa AI-gile al travalio? Dice nos qui tu es e lo que tu face. Si illo face alcun bono, le licentia es gratuite.","licence.company":"Empresa","licence.website":"Sito web","licence.what":"Lo que tu face","licence.how":"Como illo adjuta le mundo","licence.email":"E-mail","licence.submit":"Applicar","licence.thanks":"Gratias! Nos respondera per e-mail.","status.title":"Stato de AI-gile","status.h1":"Stato de AI-gile","status.quiet":"Toto es tranquille","status.intro":"Functiona AI-gile in iste momento? Iste pagina verifica le sito web, le compartimento de tabulas, le appellos e le discargamento cata 5 minutas.","status.up":"Functionante (respondeva in {ms} ms)","status.slow":"Non respondeva al ultime verification, retentante","status.down":"Foras de servicio: non respondeva al duo ultime verificationes","status.svc.web":"Sito web","status.svc.web.offers":"Iste sito: lo que AI-gile es, e le formulario de interesse","status.svc.boards":"Compartimento de tabulas","status.svc.boards.offers":"Tabulas public, messages inter amicos e invitationes","status.svc.calls":"Appellos","status.svc.calls.offers":"Voce, video e compartimento de schermo in AI-gile","status.svc.download":"Discargamento","status.svc.download.offers":"Le installator pro Windows e le ligamines de invitation","status.checking":"Verificante…","status.offline":"Non pote attinger le servicio de stato ora (retentante)","status.updated":"actualisate {ago}","status.justNow":"justo ora","status.min":"ante {n} min","status.hours":"ante {n} h","status.days":"ante {n} d","privacy.title":"AI-gile: lo que nos guarda","privacy.h1":"Lo que nos guarda","privacy.lede":"Version curte: solmente lo que tu nos invia, e non pro longe tempore.","privacy.only":"Solmente lo que tu nos invia: lo que tu scribe in un formulario, como tu e-mail. Nihil altere super te.","privacy.sealed":"Illo es sigillate de maniera que nostre servitor non pote leger lo: in tu navigator ante que illo parti (in un navigator plus vetule, al momento que illo arriva). Solmente nostre proprie tabula pote aperir lo.","privacy.server":"Illo es delite del servitor tosto que illo arriva a nostre tabula. Toto lo que resta ibi post 30 dies es delite in omne caso.","privacy.board":"Nos lo guarda sur nostre tabula solmente usque nos te ha respondite, postea nos lo dele ibi tamben.","privacy.none":"Nulle traciatores, nulle cookies, nulle analytica.","privacy.local":"Tu lingua e tu selection de modo clar o obscur resta in tu proprie navigator. Illos non es jammais inviate a nos.","privacy.ask":"Tu vole que illo dispare plus tosto? Responde a nostre e-mail e dice lo.","live.h2":"Observa lo esser construite, in directo","live.caption":"Cata carta es celate: tu vide le forma del labor, non le parolas.","live.watching.one":"in directo: {n} observa","live.watching.other":"in directo: {n} observa","live.last.now":"Ultime carta displaciate justo ora","live.last.min.one":"Ultime carta displaciate {n} min retro","live.last.min.other":"Ultime carta displaciate {n} min retro","live.last.hour.one":"Ultime carta displaciate {n} hora retro","live.last.hour.other":"Ultime carta displaciate {n} horas retro","live.last.day.one":"Ultime carta displaciate {n} die retro","live.last.day.other":"Ultime carta displaciate {n} dies retro","live.offline":"Le tabula in directo prende un pauco de respiro. Retorna tosto.","live.cols":"Backlog|A facer|In curso|Le equipa verifica|Pro que tu lo teste|Pro le equipa|Facite"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegate."]},{"n":2,"texts":["Kanban robotic.","Agentes, organisate.","Ideas, construite."]},{"n":3,"texts":["Kanban pro robots.","Ideas deveni functiones.","Kanban gratuite de agentes."]},{"n":5,"texts":["Tabula kanban gerite per agentes.","Tu scribe cartas. Agentes construe.","Gratuite, local, testate, un poco folle."]},{"n":8,"texts":["Un tabula kanban gratuite ubi agentes IA travalia.","Scribe un idea. Agentes lo construe. Tu accepta.","Agile pro un human e multe robots patiente."]},{"n":13,"texts":["Un tabula kanban sur tu computator ubi agentes IA prende le cartas.","Scribe un idea. Un equipa de agentes lo construe. Un testator lo verifica.","Gratuite, sin contos, sin traciatores: un tabula, alcun robots, e tu al commando."]},{"n":21,"texts":["AI-gile es un tabula kanban pro travaliar con agentes IA de programmation. Illes prende le cartas; tu los testa e los accepta.","Cata projecto ha un chef e un equipa de agentes IA. Commenta qualcunque carta e le equipa se mitte al travalio.","Un tabula personal e gratuite de cosas a facer que functiona sur tu proprie computator. Le obreros es robots. Qui dice si, es tu."]},{"n":34,"texts":["Tu pone ideas sur un tabula. Un equipa de agentes IA los transforma in functiones que functiona, los testa e los retorna a te con passos a probar. Nihil se considera finite usque tu lo dice.","AI-gile es un tabula kanban artisanal que Rich ha construite con multe adjuta del agentes que ille ora gere. Es gratuite, functiona sur tu computator e es partite con amicos, non vendite.","Imagina un tabula kanban ordinari, con columnas ab Backlog usque a Finite, excepte que le cartas es prendite per agentes IA. Illes reporta progresso, pone questiones quando illes es blocate, e sempre expecta tu pollice in alto."]},{"n":55,"texts":["AI-gile es un tabula kanban ubi le equipa es facite de agentes IA. Cata projecto ha un chef qui planifica le travalio e adjutatores qui lo construe. Quando un function es preste, un testator IA lo proba e prende un captura de schermo, postea illo arriva in tu pila. Accepta lo, o commenta e illes lo refacera.","Illo comenciava como un modo pro un persona de seguer multe sessiones de programmation IA al mesme tempore, e crescite in un tabula ver. Illo functiona sur tu machina, non require un conto e non ha traciatores. Es gratuite pro amicos e pro omne persona curiose. Illo es etiam non finite, dunque expecta alicun bordos rude e un surprisa de tempore a tempore.","Ecce le version honeste. Tu ancora debe haber le ideas, e tu ancora debe verificar le resultatos. Lo que AI-gile face es toto lo que es inter illos: illo tene le cartas in ordine, expergisce le agente correcte quando tu commenta, monstra exactemente lo que ha cambiate, e mitte toto in un sol curte pila pro te."]},{"n":89,"texts":["AI-gile es un tabula kanban gratuite que tu executa sur tu proprie computator. In vice de personas, cata projecto ha un equipa de agentes IA: un chef qui transforma tu ideas in cartas e un plano, e adjutatores qui prende le cartas per ordine de prioritate. Quando alco es construite, un testator IA seque le passos de test e te monstra lo que illo ha vidite. Postea illo expecta in un sol pila appellate Pro te. Tu lo accepta, o tu commenta e le equipa retenta un altere vice. Nihil jammais arriva a Finite sin te.","Alicun functiones que tu forsan non expecta. Un guarda nocturne reimple le columna A facer durante que tu dormi, eligente cartas que non require tu responsa. Un contator de jetones monstra quanto le agentes ha usate hodie e iste septimana, e le Modo Sin Jetones dice los de cessar de expender. Tu pote inviar messages a amicos, e le messages private es cryptate de fin a fin. Le tabula parla circa 120 linguas, includente nederlandese, flamingo, pirata e klingon. Toto es sin costo, e nemo tenta vender lo a te.","AI-gile es un micre projecto personal, non un empresa. Rich voleva curar plure projectos de programmation IA sin aperir cata application pro verificar los, dunque ille e le agentes ha construite un tabula pro isto, e postea ha usate le tabula pro construer le resto de se mesme. Illo es in pre-alpha claudite, lo que significa que illo functiona, plus o minus, pro un manuata de amicos. Il non ha pagina de precios, nulle newsletter e nulle plano de crescentia. Si illo sona utile, tu pote demandar de probar lo quando illo aperi un poco plus."]},{"n":144,"texts":["AI-gile es un tabula kanban pro un human e multe agentes IA. Illo functiona sur tu proprie computator e es completemente gratuite. Tu adde projectos, e cata projecto recipe un chef e un micre equipa. Tu conversa con le chef, un poco como sur Discord, e describe un idea; le chef lo transforma in cartas e un plano, postea expecta que tu preme Go. Le equipa passa per le cartas secundo prioritate, usante un simple linea de commando facite pro modellos de lingua. Ante que alco retorna a te, un testator IA seque le passos in un copia del application e attacha un captura de schermo. Le travalio finite arriva in tu pila con le files cambiate e le diff. Tu lo accepta, o tu lassa un commento e le equipa se expergisce e retenta. Solmente tu pote mover un carta a Finite.","Un die con AI-gile, plus o minus. Al vespere tu lassa alicun commentos: iste button es in le placia errate, ille lista debe esser ordinate, poterea nos haber un modo obscur. Tu va dormir. Le agentes lege le commentos, face le cambiamentos, los testa e los retorna a te. Si A facer se sicca, le guarda nocturne lo reimple ab le backlog con cartas que non require tu responsa. Al matino il ha un sol curte pila: un par de questiones e alicun cosas a probar, cata un con passos que un persona somnolente pote sequer e un captura de schermo que monstra lo functionar. Tu clicca a transverso, accepta le bon e retorna le resto. Un contator de jetones monstra quanto toto isto ha usate, e le Modo Sin Jetones es ibi pro septimanas magre. Postea tu prende le jentaculo, in le qual le agentes non pote ancora adjutar.","Primo, lo que AI-gile non es. Illo non es un startup, non es a vender, e nemo collige tu datos. Es un tabula gratuite que functiona sur tu computator, sin contos, sin traciatores e sin cookies. Lo que illo es: un sol loco ordinate pro vider tote le projectos de programmation IA al mesme tempore, con un equipa de agentes qui face le cartas e tu qui prende le decisiones. Illo fusiona cartas connexe, corrige titulos confuse, e surveglia como legier le codice remane. Illo parla circa 120 linguas, del nederlandese e flamingo al pirata e klingon. Amicos pote inviar se messages, in privato e cryptate. Illo esseva construite per Rich e un grande numero de agentes patiente, le plus del tempore usante se mesme. Illo es in pre-alpha claudite, dunque es rude in alcun locos. Si illo sona divertente, demanda amabilemente e tu poterea entrar precocemente."]}],"quips":{"1":"Un parola. Audace. Forsan troppo audace.","3":"Tres parolas. Ja plus honeste que le major parte del paginas de producto.","8":"Octo parolas. Ancora plus curte que un stand-up.","21":"Le longitudes es punctos de historia, a proposito. Naturalmente.","55":"Cinquanta-cinque parolas. Duo cartas esseva finite durante que tu legeva isto.","144":"Isto es le version longe. Il non ha 233. Le agentes ha ite a dormir."}},"timeline":{"first-idea.name":"Le prime idea","first-idea.line":"Le prime conversation, ante que existeva un sol linea de codice.","first-board.name":"Le prime tabula","first-board.line":"Un tabula que seque su proprie construction: cartas, columnas, traher e deponer, projectos.","team-roles.name":"Equipa e rolos","team-roles.line":"Profilos de agentes, modellos de equipa, spatios e qui face que.","install.name":"Installation e publicationes","install.line":"Un zip que un amico pote installar, auto-actualisation, canales e retorno al version precedente.","usage-saver.name":"Economisator de uso","usage-saver.line":"Mesura lo que le executiones costa, tene le codice legier, economisa tu limite.","friends.name":"Amicos e compartir","friends.line":"Messages private, un relais cryptate, invitationes, rolos e projectos partite.","languages.name":"Linguas","languages.line":"Cata texto de schermo in un file de lingua, con nederlandese e flamingo primo.","ai-tester.name":"Testator IA","ai-tester.line":"Un testator verifica cata consigna primo e monstra lo que illo ha vidite.","website.name":"Le sito web","website.line":"aigile.lol, le teaser e iste chronologia.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modo streamer, GIFs e emojis.","no-ai.name":"Edition sin IA","no-ai.line":"Un tabula pro personas qui programma sin IA, e tabulas public.","night-watch.name":"Guarda nocturne","night-watch.line":"Un guarda e un Scrum Master tene le equipas al tasca durante que tu dormi.","p-more.name":"Tote le resto","p-more.line":"Ideas plus micre que ancora expecta lor torno.","p-android.name":"Telephono e Android","p-android.line":"Attinge tu tabula ab un telephono, postea un application Android native.","p-release.name":"Alpha e post","p-release.line":"Alpha claudite, le sito in vivo, postea beta.","p-languages.name":"Plus linguas","p-languages.line":"Plus de cento linguas, e un modo de immersion pro apprendentes.","p-engines.name":"Plus motores IA","p-engines.line":"Elige Claude, Codex o Gemini per agente.","p-pro.name":"Practica professional","p-pro.line":"Etiquettas de risco, portas de merge, cartas de incidente e barrieras de securitate.","p-self.name":"Cura de te","p-self.line":"Modo fatigate, rememoratores de autocura e 4:20.","p-servers.name":"Servitores e scala","p-servers.line":"Configurationes global de servitor, rolos e planification pro crescer.","p-livestream.name":"Extras de streaming","p-livestream.line":"Chat de Twitch, emojis personalisate e un vista public in vivo."},"words":{"button":"📖 Parolas de programmator","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Cercar un parola…","none":"Nulle parola corresponde.","close":"Clauder","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Le dossier del codice del projecto e su historia complete de commits, usualmente etiam tenite sur GitHub.","also":["deposito"]},{"id":"branch","g":"build","word":"Ramo","text":"Un linea separate de labor in le codice, de modo que cambiamentos pote esser facite sin tangere le version principal.","also":["ramos"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantanea salvate del codice, con un breve nota de lo que cambiava. Tu sempre pote retornar a un.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Inviar instantaneas salvate (commits) de iste computator a GitHub, de modo que illos es salvate e compartite."},{"id":"merge","g":"build","word":"Fusion","text":"Junger le cambiamentos de un ramo de novo al version principal."},{"id":"pr","g":"build","word":"Pull request","text":"Demandar que le cambiamentos de un ramo es verificate e fusionate in le version principal.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactorisation","text":"Ordinar le codice sin cambiar lo que illo face: files plus parve, nomines plus clar, minus repetition."},{"id":"bug","g":"build","word":"Error","text":"Qualcosa que non functiona como illo debe.","also":["errores"]},{"id":"test","g":"build","word":"Test","text":"Probar un labor finite pro verificar que illo face lo que esseva demandate, ante que tu lo accepta.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Disponer","text":"Poner un nove version in linea, per exemplo sur un servitor ubi le gente lo usa."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideas e labor non planificate ancora. Nihil ibi es elaborate usque illo se move a A facer."},{"id":"sprint","g":"team","word":"Sprint","text":"Un breve periodo de labor (sovente un septimana o duo) con un serie convenite de cartas a finir.","also":["sprints"]},{"id":"standup","g":"team","word":"Reunion stante","text":"Un verification rapide: lo que cata membro del equipa ha facite, lo que illo face proxime, e lo que lo arresta.","also":["reunion stante","reuniones stante"]},{"id":"kanban","g":"team","word":"Kanban","text":"Un tabula con columnas (A facer, In curso, Facite) ubi cartas se move de sinistra a dextra durante que le labor occurre."},{"id":"wip","g":"team","word":"Limite WIP","text":"Labor in curso: le maxime de cartas que un columna debe continer, de modo que le equipa termina cosas ante de initiar plus.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Un IA que travalia per se mesme sur un tasca: lege le codice, face cambiamentos, executa verificationes e reporta.","also":["agentes"]},{"id":"token","g":"team","word":"Jeton","text":"Le unitate in que le uso de IA es contate: approximativemente alcun litteras de texto legite o scribite. Minus jetones, plus de tu plano resta.","also":["jetones"]},{"id":"hook","g":"team","word":"Hook","text":"Un parve commando que executa per se mesme a un momento definite, p.ex. quando un session de IA initia, de modo que le equipa audi tu commentos.","also":["hooks"]}]}};
